import Foundation

// MARK: - Subway map (lines and stations)
//
// Data comes from MTA's official static GTFS (gtfs_subway.zip, free, no key needed):
// line colors from routes.txt, line paths from trips.txt + shapes.txt, stations from stops.txt.
// A copy ships with the app (Resources/subway_map.json, generated by tools/generate_map.py), so it works offline;
// on the first map open after the 1st of each month, the app checks whether MTA has new data and replaces the old with it if so.

public struct SubwayMap: Codable, Sendable, Equatable {

    public struct Route: Codable, Sendable, Equatable {
        public var route: String
        /// Line color, hex (e.g. "0062CF")
        public var color: String
        /// Simplified polyline; each point is [latitude, longitude]
        public var lines: [[[Double]]]
    }

    public struct Station: Sendable, Equatable {
        public var id: String
        public var name: String
        public var lat: Double
        public var lon: Double

        public init(id: String, name: String, lat: Double, lon: Double) {
            self.id = id
            self.name = name
            self.lat = lat
            self.lon = lon
        }
    }

    public var source: String
    public var feedVersion: String
    public var stations: [Station]
    public var routes: [Route]

    public init(source: String, feedVersion: String, stations: [Station], routes: [Route]) {
        self.source = source
        self.feedVersion = feedVersion
        self.stations = stations
        self.routes = routes
    }

    /// Draw two maps together (bus: MTA bus + NJ Transit and a few others). Keeps all stations and lines; for stations with the same id only the first map's is kept.
    public func merged(with other: SubwayMap) -> SubwayMap {
        let ids = Set(stations.map(\.id))
        return SubwayMap(source: source,
                         feedVersion: [feedVersion, other.feedVersion].filter { !$0.isEmpty }.joined(separator: " + "),
                         stations: stations + other.stations.filter { !ids.contains($0.id) },
                         routes: routes + other.routes)
    }

    // Stations are stored in the file as [id, name, lat, lon], half the space of objects
    private enum CodingKeys: String, CodingKey { case source, feedVersion, stations, routes }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        source = try c.decodeIfPresent(String.self, forKey: .source) ?? ""
        feedVersion = try c.decodeIfPresent(String.self, forKey: .feedVersion) ?? ""
        routes = try c.decode([Route].self, forKey: .routes)
        var list = try c.nestedUnkeyedContainer(forKey: .stations)
        var result: [Station] = []
        while !list.isAtEnd {
            var row = try list.nestedUnkeyedContainer()
            let id = try row.decode(String.self)
            let name = try row.decode(String.self)
            let lat = try row.decode(Double.self)
            let lon = try row.decode(Double.self)
            result.append(Station(id: id, name: name, lat: lat, lon: lon))
        }
        stations = result
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        try c.encode(source, forKey: .source)
        try c.encode(feedVersion, forKey: .feedVersion)
        var list = c.nestedUnkeyedContainer(forKey: .stations)
        for s in stations {
            var row = list.nestedUnkeyedContainer()
            try row.encode(s.id)
            try row.encode(s.name)
            try row.encode(s.lat)
            try row.encode(s.lon)
        }
        try c.encode(routes, forKey: .routes)
    }

    public static func decode(_ data: Data) throws -> SubwayMap {
        try JSONDecoder().decode(SubwayMap.self, from: data)
    }

    public func encoded() throws -> Data {
        try JSONEncoder().encode(self)
    }

    /// MTA's subway static GTFS, in code: the monthly check builds the map, the station list and the trip planner's timetable from it
    public static let builtInSourceURL = URL(string: "https://rrgtfsfeeds.s3.amazonaws.com/gtfs_subway.zip")!

    /// Its address: the source list's, or the one in code
    public static var sourceURL: URL { SourceList.timetableURL(for: "mta-subway") ?? builtInSourceURL }

    /// The built-in copy.
    public static func loadBundled() throws -> SubwayMap {
        guard let url = Bundle.module.url(forResource: "subway_map", withExtension: "json") else {
            throw CocoaError(.fileNoSuchFile)
        }
        return try decode(Data(contentsOf: url))
    }

    /// The station nearest to a coordinate and the straight-line distance (meters).
    public func nearestStation(to coordinate: Coordinate) -> (station: Station, meters: Double)? {
        stations
            .map { ($0, WalkEstimator.distanceMeters(coordinate, Coordinate(latitude: $0.lat, longitude: $0.lon))) }
            .min { $0.1 < $1.1 }
            .map { (station: $0.0, meters: $0.1) }
    }
}

// MARK: - Monthly check

public enum SubwayMapSchedule {
    /// This Mac's calendar: the checks are the app's own, so "the 1st of each month" is the 1st where the Mac is, in every area,
    /// as are the dates shown with them (a Mac west of New York would otherwise see a check on the last day of the month before)
    public static var calendar: Calendar { Timetable.calendar(in: .autoupdatingCurrent) }

    /// Midnight on the 1st of this month (this Mac's time).
    public static func startOfMonth(_ date: Date, calendar: Calendar = calendar) -> Date {
        calendar.dateInterval(of: .month, for: date)?.start ?? date
    }

    /// Based on the 1st of each month: a check is due if the last one was before the 1st of this month (or never happened).
    public static func isDue(lastChecked: Date?, now: Date = Date(), calendar: Calendar = calendar) -> Bool {
        guard let lastChecked else { return true }
        return lastChecked < startOfMonth(now, calendar: calendar)
    }

    /// Date of the next check: the 1st of next month.
    public static func nextCheck(after lastChecked: Date, calendar: Calendar = calendar) -> Date {
        let start = startOfMonth(lastChecked, calendar: calendar)
        return calendar.date(byAdding: .month, value: 1, to: start) ?? start
    }
}

/// One data store's monthly check, kept per operator: which operators this month's check has already refreshed,
/// and how long to wait before trying again an operator that failed (10 minutes, doubling with each failure in a row, at most a day).
/// So one operator that keeps failing never makes the others download again, and the month only counts as checked once every operator got through.
public struct MonthlyCheck: Sendable {
    public static let firstRetry: TimeInterval = 600
    public static let longestRetry: TimeInterval = 24 * 3600

    struct Failure: Sendable {
        var count: Int
        var at: Date
        /// How long it waits, when it isn't the doubling one: an operator held back because its new data looked wrong (see held)
        var wait: TimeInterval?
    }
    struct Progress: Sendable {
        /// lastChecked when this month's check started (a check finished elsewhere since then starts over)
        var due: Date?
        var month: Date
        var done: Set<String>
    }
    private var failures: [String: Failure] = [:]
    private var progress: Progress?

    public init() {}

    /// Some operator's last download failed (one held back because its new data looked wrong downloaded fine: not counted)
    public var hasFailures: Bool { failures.values.contains { $0.wait == nil } }

    /// An operator that never failed, or whose wait after its last failure is over
    public func canRetry(_ key: String, now: Date) -> Bool {
        guard let f = failures[key] else { return true }
        let wait = f.wait ?? min(Self.longestRetry, Self.firstRetry * pow(2, Double(f.count - 1)))
        return now.timeIntervalSince(f.at) >= wait
    }

    /// The operators this month's check still has to download now: all of them before it starts; afterwards only the ones not yet refreshed,
    /// each once its wait is over. `downloaded`: when each operator last downloaded fine, as the app keeps it across launches (see
    /// DownloadDates); one downloaded since the month began counts as refreshed, so it isn't downloaded again after a relaunch
    public func remaining(of all: Set<String>, lastChecked: Date?, now: Date, downloaded: [String: Date] = [:]) -> Set<String> {
        all.subtracting(done(lastChecked: lastChecked, now: now, downloaded: downloaded)).filter { canRetry($0, now: now) }
    }

    private func done(lastChecked: Date?, now: Date, downloaded: [String: Date]) -> Set<String> {
        let month = SubwayMapSchedule.startOfMonth(now)
        let thisMonth = Set(downloaded.filter { $0.value >= month }.map(\.key))
        guard let progress, progress.due == lastChecked, progress.month == month else { return thisMonth }
        return progress.done.union(thisMonth)
    }

    /// Tries every failed operator again right away: the source list changed, and the address that failed may have moved
    public mutating func forgetFailures() {
        failures = [:]
    }

    public mutating func failed(_ keys: Set<String>, now: Date) {
        for key in keys { failures[key] = Failure(count: (failures[key]?.count ?? 0) + 1, at: now) }
    }

    /// These operators downloaded fine, but their new data looked wrong and wasn't taken (DataUpdateGate): this month's check
    /// isn't done for them, and they're downloaded again after DataChangeLog.recheckHours, not 10 minutes later
    public mutating func held(_ keys: Set<String>, now: Date) {
        for key in keys { failures[key] = Failure(count: 1, at: now, wait: Double(DataChangeLog.recheckHours) * 3600) }
    }

    /// Records the operators that just downloaded fine. Returns true once every operator in `all` has been refreshed this month: the monthly check is done.
    public mutating func refreshed(_ keys: Set<String>, of all: Set<String>, lastChecked: Date?, now: Date,
                                   downloaded: [String: Date] = [:]) -> Bool {
        for key in keys { failures[key] = nil }
        let done = done(lastChecked: lastChecked, now: now, downloaded: downloaded).union(keys)
        if all.isSubset(of: done) {
            progress = nil
            return true
        }
        progress = Progress(due: lastChecked, month: SubwayMapSchedule.startOfMonth(now), done: done)
        return false
    }
}

/// When each operator of one data store last downloaded and read fine (by its MonthlyCheck key), kept across launches by the app:
/// the day a mode's timetables are up to date as of
public enum DownloadDates {
    /// The earliest of these operators' last good downloads, so the day only moves on once every operator got through.
    /// nil while one of them has none (it never downloaded)
    public static func upToDate(_ dates: [String: Date], of operators: Set<String>) -> Date? {
        guard !operators.isEmpty else { return nil }
        var earliest = Date.distantFuture
        for key in operators {
            guard let date = dates[key] else { return nil }
            earliest = min(earliest, date)
        }
        return earliest
    }

    /// The dates to start from when none are saved yet (kept per operator only since this version): every operator from the store's
    /// last full check, which only came once every one of them got through; none before it ever finished one
    public static func starting(lastChecked: Date?, operators: Set<String>) -> [String: Date] {
        guard let lastChecked else { return [:] }
        return Dictionary(uniqueKeysWithValues: operators.map { ($0, lastChecked) })
    }

    /// The date shown with "next check": the 1st of next month, never a day already past (a check goes on retrying an operator that
    /// keeps failing, and the month counts as checked only once every one got through)
    public static func nextCheck(now: Date = Date()) -> Date {
        SubwayMapSchedule.nextCheck(after: now)
    }
}

// MARK: - Building the map from GTFS text (same approach as tools/generate_map.py)

public enum SubwayMapBuilder {
    /// Douglas-Peucker simplification tolerance, about 8 meters
    static let tolerance = 0.00008

    /// - Parameter files: routes.txt, trips.txt, shapes.txt, stops.txt (feed_info.txt optional).
    public static func build(files: [String: Data]) throws -> SubwayMap {
        for name in ["routes.txt", "trips.txt", "shapes.txt", "stops.txt"] where files[name] == nil {
            throw TimetableError.missingFile(name)
        }
        var colors: [String: String] = [:]
        try TimetableBuilder.forEachRow(files["routes.txt"]!) { col in
            guard let id = col("route_id") else { return }
            let c = col("route_color") ?? ""
            colors[id] = c.isEmpty ? "808183" : c
        }
        var shapeRoute: [String: String] = [:]
        try TimetableBuilder.forEachRow(files["trips.txt"]!) { col in
            guard let shape = col("shape_id"), !shape.isEmpty, let route = col("route_id") else { return }
            if shapeRoute[shape] == nil { shapeRoute[shape] = route }
        }
        // Keep only northbound (N) paths, to avoid drawing the same segment twice
        var points: [String: [(Int, Double, Double)]] = [:]
        try TimetableBuilder.forEachRow(files["shapes.txt"]!) { col in
            guard let shape = col("shape_id"), shapeRoute[shape] != nil, shape.contains(".N"),
                  let seq = col("shape_pt_sequence").flatMap({ Int($0) }),
                  let lat = col("shape_pt_lat").flatMap({ Double($0) }),
                  let lon = col("shape_pt_lon").flatMap({ Double($0) }) else { return }
            points[shape, default: []].append((seq, lat, lon))
        }
        var routeLines: [String: [[[Double]]]] = [:]
        for shape in points.keys.sorted() {
            let pts = points[shape]!.sorted { $0.0 < $1.0 }.map { ($0.1, $0.2) }
            let line = simplify(pts).map { [round5($0.0), round5($0.1)] }
            routeLines[shapeRoute[shape]!, default: []].append(line)
        }
        var stations: [SubwayMap.Station] = []
        try TimetableBuilder.forEachRow(files["stops.txt"]!) { col in
            guard col("location_type") == "1", let id = col("stop_id"), let name = col("stop_name"),
                  let lat = col("stop_lat").flatMap({ Double($0) }),
                  let lon = col("stop_lon").flatMap({ Double($0) }) else { return }
            stations.append(.init(id: id, name: name, lat: round5(lat), lon: round5(lon)))
        }
        var version = ""
        if let info = files["feed_info.txt"] {
            var first = true
            try TimetableBuilder.forEachRow(info) { col in
                if first { version = col("feed_version") ?? ""; first = false }
            }
        }
        let routes = routeLines.keys.sorted().map {
            SubwayMap.Route(route: $0, color: colors[$0] ?? "808183", lines: routeLines[$0]!)
        }
        guard !routes.isEmpty, !stations.isEmpty else { throw TimetableError.missingFile("shapes.txt") }
        return SubwayMap(source: "MTA static GTFS (rrgtfsfeeds gtfs_subway.zip)", feedVersion: version,
                         stations: stations, routes: routes)
    }

    static func round5(_ v: Double) -> Double { (v * 100_000).rounded() / 100_000 }

    /// Douglas-Peucker polyline simplification. Points are (latitude, longitude).
    static func simplify(_ points: [(Double, Double)], tolerance: Double = tolerance) -> [(Double, Double)] {
        guard points.count >= 3 else { return points }
        var keep = [Bool](repeating: false, count: points.count)
        keep[0] = true
        keep[points.count - 1] = true
        var stack = [(0, points.count - 1)]
        while let (a, b) = stack.popLast() {
            let (ay, ax) = points[a], (by, bx) = points[b]
            let dx = bx - ax, dy = by - ay
            let norm = (dx * dx + dy * dy).squareRoot()
            var best = 0.0, idx = -1
            if b - a >= 2 {
                for i in (a + 1)..<b {
                    let (py, px) = points[i]
                    let d = norm == 0
                        ? ((px - ax) * (px - ax) + (py - ay) * (py - ay)).squareRoot()
                        : abs(dy * px - dx * py + bx * ay - by * ax) / norm
                    if d > best { best = d; idx = i }
                }
            }
            if best > tolerance && idx > 0 {
                keep[idx] = true
                stack.append((a, idx))
                stack.append((idx, b))
            }
        }
        return zip(points, keep).filter(\.1).map(\.0)
    }
}

// MARK: - Walking-time labels beside the stations in range (transit map)

/// Where the labels beside the stations in walking range go on the transit map: the walking minutes over the station name, as in
/// the station list. Plain geometry in screen points (the app measures the labels and turns coordinates into points), so it's tested here.
/// Stations come in the list's order, nearest first, and each takes the first free place: beside the station (right, or left in a
/// right-to-left language), then the other side, above, below; then the same four with the minutes only; else no label for now
/// (zooming in makes room). A label stays inside the map and never covers another label, another station in range,
/// or an area kept clear (the buttons and legend, the station card, where you are). A complex has several dots: its label keeps
/// clear of the others too when it can, if need be moved out past them, or else put beside one of them, so it stands beside the
/// whole complex.
public enum MapLabelLayout {
    /// No labels while the extended range's circle is smaller than this on screen (radius, points): zoomed out that far they'd only pile up
    public static let minRangeRadius: Double = 70
    /// On the bus map only the nearest few stops get a label: there are often a few dozen stops in range
    public static let busLabelLimit = 5
    /// Space kept between two labels, and between a label and an area kept clear
    static let labelSpacing: Double = 3
    static let clearSpacing: Double = 2
    /// How far a label may be moved out past its own complex's other dots (points): further out it would no longer read as its station's
    static let maxSlide: Double = 60

    public struct Box: Equatable, Sendable {
        public var x: Double
        public var y: Double
        public var width: Double
        public var height: Double

        public init(x: Double, y: Double, width: Double, height: Double) {
            self.x = x
            self.y = y
            self.width = width
            self.height = height
        }

        public var maxX: Double { x + width }
        public var maxY: Double { y + height }

        /// Overlaps `other`, or comes closer to it than `spacing`
        public func touches(_ other: Box, spacing: Double = 0) -> Bool {
            x < other.maxX + spacing && other.x < maxX + spacing && y < other.maxY + spacing && other.y < maxY + spacing
        }

        /// `other` lies wholly inside
        public func contains(_ other: Box) -> Bool {
            other.x >= x && other.y >= y && other.maxX <= maxX && other.maxY <= maxY
        }
    }

    public struct Size: Equatable, Sendable {
        public var width: Double
        public var height: Double

        public init(width: Double, height: Double) {
            self.width = width
            self.height = height
        }
    }

    /// Which side of the station a label is on (on screen: left and right don't swap in right-to-left languages)
    public enum Side: String, Sendable {
        case right, left, above, below
    }

    /// One station to label: where the station is on screen, and the label's size with the name and with the minutes only
    public struct Item: Equatable, Sendable {
        public var id: String
        public var x: Double
        public var y: Double
        public var full: Size
        public var compact: Size

        public init(id: String, x: Double, y: Double, full: Size, compact: Size) {
            self.id = id
            self.x = x
            self.y = y
            self.full = full
            self.compact = compact
        }
    }

    public struct Placement: Equatable, Sendable {
        public var id: String
        public var side: Side
        /// Minutes only: no room for the name
        public var compact: Bool
        public var box: Box
        /// The station's point inside the label's box, as a fraction of its width and height (outside 0...1: the station is beside the label).
        /// Pinning this point of the label to the station puts the label where `box` is
        public var anchorX: Double
        public var anchorY: Double
    }

    /// Whether to draw labels at all, from the extended range's radius on screen (points)
    public static func showsLabels(rangeRadius: Double) -> Bool {
        rangeRadius >= minRangeRadius
    }

    /// - Parameters:
    ///   - items: the stations to label, nearest first (the station list's order)
    ///   - bounds: the visible map
    ///   - keepClear: areas no label may cover
    ///   - dots: the stations in range as drawn on the map, by the id of the label they belong to (a complex has several);
    ///     a label never covers another label's. Its own complex's other dots (not the one it stands beside) it keeps clear of too:
    ///     beside its station if there's room, else moved out past those in the way (at most `maxSlide`, and never past another
    ///     station's dot or label), else beside another of its dots (nearest first), unless the label then fits nowhere at that
    ///     size. Stations without a label keep their own ids
    ///   - gap: from the station's point to the label's near edge
    ///   - rightToLeft: try the left side first
    /// - Returns: the labels that fit, in the order of `items`. A station off the map gets none
    public static func place(_ items: [Item], in bounds: Box, keepClear: [Box] = [], dots: [String: [Box]] = [:],
                             gap: Double, rightToLeft: Bool) -> [Placement] {
        let sides: [Side] = rightToLeft ? [.left, .right, .above, .below] : [.right, .left, .above, .below]
        var placed: [Placement] = []
        for item in items {
            guard bounds.contains(Box(x: item.x, y: item.y, width: 0, height: 0)) else { continue }
            let others = dots.filter { $0.key != item.id }.flatMap(\.value)
            // The other dots of its own complex (not the one it stands beside): kept clear of when there's room
            let point = Box(x: item.x, y: item.y, width: 0, height: 0)
            let siblings = (dots[item.id] ?? []).filter { !$0.contains(point) }
            let own = (dots[item.id] ?? []).filter { $0.contains(point) }
            func isFree(_ box: Box, clearOfSiblings: Bool) -> Bool {
                bounds.contains(box)
                    && !placed.contains { $0.box.touches(box, spacing: labelSpacing) }
                    && !keepClear.contains { $0.touches(box, spacing: clearSpacing) }
                    && !others.contains { $0.touches(box) }
                    && !(clearOfSiblings && siblings.contains { $0.touches(box) })
            }
            // The label on that side moved out past the dots of its own complex in its way. Nil when none is in the way (that place
            // was tried already), when it would go further than maxSlide, or when another station's dot or label would come between
            // the label and its station
            func slid(_ side: Side, size: Size) -> Box? {
                let start = frame(side, size: size, x: item.x, y: item.y, gap: gap)
                var box = start
                while let dot = siblings.first(where: { $0.touches(box) }) {
                    switch side {
                    case .right: box.x = dot.maxX + clearSpacing
                    case .left: box.x = dot.x - clearSpacing - box.width
                    case .below: box.y = dot.maxY + clearSpacing
                    case .above: box.y = dot.y - clearSpacing - box.height
                    }
                    guard abs(box.x - start.x) + abs(box.y - start.y) <= maxSlide else { return nil }
                }
                guard box != start else { return nil }
                let path = Box(x: min(start.x, box.x), y: min(start.y, box.y),
                               width: abs(box.x - start.x) + box.width, height: abs(box.y - start.y) + box.height)
                guard !others.contains(where: { $0.touches(path) }), !placed.contains(where: { $0.box.touches(path) }) else { return nil }
                return box
            }
            // The label on that side of another dot of its own complex: for a complex spread out so far that there's no room by
            // the dot it stands beside, nor past its other dots. Nil when it would cover that dot
            func besideSibling(_ dot: Box, _ side: Side, size: Size) -> Box? {
                let box = frame(side, size: size, x: dot.x + dot.width / 2, y: dot.y + dot.height / 2, gap: gap)
                return own.contains { $0.touches(box) } ? nil : box
            }
            func put(_ side: Side, _ box: Box, compact: Bool) {
                placed.append(Placement(id: item.id, side: side, compact: compact, box: box,
                                        anchorX: (item.x - box.x) / box.width, anchorY: (item.y - box.y) / box.height))
            }
            // The whole label over one of its own station's dots rather than the minutes only
            search: for compact in [false, true] {
                let size = compact ? item.compact : item.full
                guard size.width > 0, size.height > 0 else { continue }
                for clearOfSiblings in siblings.isEmpty ? [false] : [true, false] {
                    for side in sides {
                        let box = frame(side, size: size, x: item.x, y: item.y, gap: gap)
                        if isFree(box, clearOfSiblings: clearOfSiblings) {
                            put(side, box, compact: compact)
                            break search
                        }
                    }
                    // Beside the whole complex rather than over one of its dots: moved out past them, else by another of them
                    if clearOfSiblings {
                        for side in sides {
                            if let box = slid(side, size: size), isFree(box, clearOfSiblings: true) {
                                put(side, box, compact: compact)
                                break search
                            }
                        }
                        for dot in siblings {
                            for side in sides {
                                if let box = besideSibling(dot, side, size: size), isFree(box, clearOfSiblings: true) {
                                    put(side, box, compact: compact)
                                    break search
                                }
                            }
                        }
                    }
                }
            }
        }
        return placed
    }

    /// The label's box on one side of the station: centered on it the other way
    static func frame(_ side: Side, size: Size, x: Double, y: Double, gap: Double) -> Box {
        switch side {
        case .right: return Box(x: x + gap, y: y - size.height / 2, width: size.width, height: size.height)
        case .left: return Box(x: x - gap - size.width, y: y - size.height / 2, width: size.width, height: size.height)
        case .above: return Box(x: x - size.width / 2, y: y - gap - size.height, width: size.width, height: size.height)
        case .below: return Box(x: x - size.width / 2, y: y + gap, width: size.width, height: size.height)
        }
    }
}

/// The station dots on the transit maps. Out of walking range they're sized in meters, so they grow and shrink with the map. In range
/// they're too while zoomed out, but zoomed in closer than `fixedFrom` meters a point they're drawn at a fixed size on screen instead
/// (`fixedDiameter`, as big as they are there in meters, so they don't jump): stations close together then come apart as you zoom in.
/// No dot changes size as the map zooms: making the dots in meters smaller at every zoom step made zooming slow.
public enum MapDotSize {
    /// Meters per point below which the stations in range are drawn at their fixed size
    public static let fixedFrom: Double = 5

    /// Whether the stations in range are drawn at their fixed size at this zoom (not while the map's scale isn't known)
    public static func isFixed(metersPerPoint: Double) -> Bool {
        metersPerPoint > 0 && metersPerPoint < fixedFrom
    }

    /// The fixed size on screen, in points across, of a dot `meters` in radius
    public static func fixedDiameter(_ meters: Double) -> Double {
        2 * meters / fixedFrom
    }

    /// How many points across a station-in-range dot `meters` in radius is at this zoom: in meters, at most the fixed size
    public static func diameter(_ meters: Double, metersPerPoint: Double) -> Double {
        guard metersPerPoint > 0 else { return fixedDiameter(meters) }
        return min(2 * meters / metersPerPoint, fixedDiameter(meters))
    }
}

// MARK: - Favorite places on the transit map

/// The favorite places on the transit map: a gold star each, or a small one on the station's dot for a favorite that is a station
/// of the map (saved from the station's card), and none for the starting point (its pin is there). Stars closer together on screen
/// than `mergeDistance` are drawn as one, with how many it stands for, so even 50 favorites don't cover the map zoomed out.
/// Clicking such a star zooms in until they come apart, or lists them when they're too close together to (two names for one
/// spot). Plain geometry in screen points, like the labels' (the app turns coordinates into points), so it's tested here.
public enum FavoriteMarks {
    /// Stars whose centers are closer together than this on screen (points) are drawn as one
    public static let mergeDistance: Double = 26
    /// Clicking a star that stands for several favorites zooms in to an area this many times as wide and high as the one they're in
    public static let zoomRoom: Double = 1.5
    /// ... but no closer than this many meters across the view: favorites that would still be one star there are listed instead
    public static let closestZoomMeters: Double = 300

    /// One favorite on the map: its place in the favorites list, where it is, and where that is on the view (points)
    public struct Point: Equatable, Sendable {
        public var index: Int
        public var coordinate: Coordinate
        public var x: Double
        public var y: Double

        public init(index: Int, coordinate: Coordinate, x: Double, y: Double) {
            self.index = index
            self.coordinate = coordinate
            self.x = x
            self.y = y
        }
    }

    /// One star on the map: the favorites it stands for (their places in the list, in order), and where it's drawn: in the
    /// middle of them, on the map and on the view (points)
    public struct Mark: Equatable, Sendable {
        public var members: [Int]
        public var coordinate: Coordinate
        public var x: Double
        public var y: Double

        public var count: Int { members.count }
    }

    /// The favorites the map draws, by their places in the list: all but the starting point (when it's a favorite, its pin is
    /// there and its card has the star)
    public static func drawn(_ favorites: [UserPlace], origin: UserPlace?) -> [Int] {
        favorites.indices.filter { i in origin.map { !PlaceLists.sameFavorite(favorites[i], $0) } ?? true }
    }

    /// Which station of the map each favorite is, by its place in the list (the station's id): one saved from the station's card
    /// has its name and is within 30 m of it (the same favorite, PlaceLists.sameFavorite). The nearest such dot, as a complex has
    /// several; a dot is one favorite's at most, the first in the list's
    public static func stations(of favorites: [UserPlace], on stations: [SubwayMap.Station]) -> [Int: String] {
        var byName: [String: [SubwayMap.Station]] = [:]
        for s in stations { byName[s.name, default: []].append(s) }
        var result: [Int: String] = [:]
        var taken = Set<String>()
        for (i, favorite) in favorites.enumerated() {
            let matches = (byName[favorite.name] ?? []).filter { s in
                !taken.contains(s.id)
                    && PlaceLists.sameFavorite(UserPlace(name: s.name, coordinate: Coordinate(latitude: s.lat, longitude: s.lon)), favorite)
            }
            let distance = { (s: SubwayMap.Station) in
                WalkEstimator.distanceMeters(Coordinate(latitude: s.lat, longitude: s.lon), favorite.coordinate)
            }
            guard let nearest = matches.min(by: { distance($0) < distance($1) }) else { continue }
            result[i] = nearest.id
            taken.insert(nearest.id)
        }
        return result
    }

    /// The stars for these favorites where they are on the view now: the two closest together are made one, in the middle of the
    /// favorites it then stands for, again and again until no two are closer together than `distance`. In the list's order (by
    /// each star's first favorite), so the stars keep their order as the map moves
    public static func marks(_ points: [Point], distance: Double = mergeDistance) -> [Mark] {
        var groups = points.map { [$0] }
        func middle(_ group: [Point]) -> (x: Double, y: Double) {
            let n = Double(group.count)
            return (group.map(\.x).reduce(0, +) / n, group.map(\.y).reduce(0, +) / n)
        }
        while groups.count > 1 {
            let middles = groups.map(middle)
            var closest: (i: Int, j: Int, apart: Double)?
            for i in groups.indices {
                for j in groups.indices where j > i {
                    let apart = hypot(middles[i].x - middles[j].x, middles[i].y - middles[j].y)
                    if apart < distance, apart < closest?.apart ?? .infinity { closest = (i, j, apart) }
                }
            }
            guard let closest else { break }
            groups[closest.i] += groups.remove(at: closest.j)
        }
        return groups.map { group in
            let members = group.sorted { $0.index < $1.index }
            let m = middle(group)
            return Mark(members: members.map(\.index), coordinate: center(members.map(\.coordinate)), x: m.x, y: m.y)
        }
        .sorted { ($0.members.first ?? 0) < ($1.members.first ?? 0) }
    }

    /// A box on the map's view, in points from its top left: a star, or the starting point's pin that stars keep clear of
    public struct Box: Equatable, Sendable {
        public var x: Double
        public var y: Double
        public var width: Double
        public var height: Double

        public init(x: Double, y: Double, width: Double, height: Double) {
            self.x = x
            self.y = y
            self.width = width
            self.height = height
        }

        /// Whether the two cover some of the same points (only touching at an edge isn't)
        func overlaps(_ other: Box) -> Bool {
            x < other.x + other.width && other.x < x + width && y < other.y + other.height && other.y < y + height
        }
    }

    /// Room between a star moved aside and the starting point's pin (points)
    public static let originGap: Double = 2

    /// How far each star moves sideways (points; more than 0 is to the right) to keep clear of the starting point (`origin`: its
    /// pin, or the current location's dot), so the pin covers no star and a click on its head opens the starting point's card.
    /// A star that touches it goes just beside it, `gap` away: to the right, or the left when there it would run off the view
    /// (`viewWidth` points wide) or onto another star; right-to-left layouts try the left first, as the stations' labels do.
    /// When neither side is free it takes the first side tried. Stars that don't touch it stay where they are
    public static func offsets(_ stars: [Box], clearOf origin: Box, viewWidth: Double, rightToLeft: Bool = false,
                               gap: Double = originGap) -> [Double] {
        stars.indices.map { i in
            let star = stars[i]
            guard star.overlaps(origin) else { return 0 }
            let right = origin.x + origin.width + gap - star.x
            let left = origin.x - gap - (star.x + star.width)
            let free = { (dx: Double) -> Bool in
                let moved = Box(x: star.x + dx, y: star.y, width: star.width, height: star.height)
                return moved.x >= 0 && moved.x + moved.width <= viewWidth
                    && !stars.indices.contains { $0 != i && stars[$0].overlaps(moved) }
            }
            let sides = rightToLeft ? [left, right] : [right, left]
            return sides.first(where: free) ?? sides[0]
        }
    }

    /// What clicking a star that stands for several favorites does
    public enum Zoom: Equatable, Sendable {
        /// Zooms in to this area of the map (in map points, as MKMapRect), the view's shape
        case area(x: Double, y: Double, width: Double, height: Double)
        /// They'd still be one star zoomed in as close as it goes: lists them
        case list
    }

    /// What clicking the star for favorites at these places does on a view this many points wide and high: zooms in to the
    /// area they're in, with room around it (zoomRoom), around their middle, but to no less than closestZoomMeters across; or
    /// lists them when they'd still be one star there
    public static func zoom(_ places: [Coordinate], viewWidth: Double, viewHeight: Double) -> Zoom {
        guard places.count > 1, viewWidth > 0, viewHeight > 0 else { return .list }
        let points = places.map(MapProjection.mapPoint)
        let xs = points.map(\.x), ys = points.map(\.y)
        guard let minX = xs.min(), let maxX = xs.max(), let minY = ys.min(), let maxY = ys.max() else { return .list }
        let midX = (minX + maxX) / 2, midY = (minY + maxY) / 2
        let metersPerMapPoint = MapProjection.metersPerMapPointAtEquator * cos(MapProjection.latitude(atMapY: midY) * .pi / 180)
        // Map points per point of the view
        let scale = max((maxX - minX) * zoomRoom / viewWidth, (maxY - minY) * zoomRoom / viewHeight,
                        closestZoomMeters / metersPerMapPoint / viewWidth)
        let there = points.indices.map { i in
            Point(index: i, coordinate: places[i], x: (points[i].x - midX) / scale, y: (points[i].y - midY) / scale)
        }
        guard marks(there).count > 1 else { return .list }
        let width = viewWidth * scale, height = viewHeight * scale
        return .area(x: midX - width / 2, y: midY - height / 2, width: width, height: height)
    }

    /// The middle of these places on the map (as the map draws them, in map points): where a star standing for them is drawn
    static func center(_ places: [Coordinate]) -> Coordinate {
        guard places.count > 1 else { return places.first ?? Coordinate(latitude: 0, longitude: 0) }
        let points = places.map(MapProjection.mapPoint)
        let n = Double(points.count)
        let x = points.map(\.x).reduce(0, +) / n, y = points.map(\.y).reduce(0, +) / n
        return Coordinate(latitude: MapProjection.latitude(atMapY: y), longitude: x / MapProjection.worldSize * 360 - 180)
    }
}
